    // Add your limericks here
];

function renderLimericks() {
    const container = document.getElementById('limericks');
    container.innerHTML = '';

    limericks.forEach((limerick) => {
        const li = document.createElement('li');
        li.textContent = limerick;
        container.appendChild(li);
    });
}

renderLimericks();
```

